package com.aicommerce.platform.delivery.application.port;
import java.util.*; import com.aicommerce.platform.delivery.domain.*;
public record NormalizedPlatformEvidence(int schemaVersion,ProviderKey providerKey,PlatformAttemptKind attemptKind,PlatformEvidenceResultKind resultKind,Optional<String> externalIdFingerprint,Optional<PlatformObservedState> observedState,Optional<Integer> retryAfterSeconds){public NormalizedPlatformEvidence{PlatformContractSupport.req(providerKey);PlatformContractSupport.req(attemptKind);PlatformContractSupport.req(resultKind);externalIdFingerprint=PlatformContractSupport.opt(externalIdFingerprint);observedState=PlatformContractSupport.opt(observedState);retryAfterSeconds=PlatformContractSupport.opt(retryAfterSeconds);externalIdFingerprint.ifPresent(PlatformContractSupport::hash);if(schemaVersion!=1||(providerKey!=ProviderKey.FAKE&&providerKey!=ProviderKey.FAKE_GOOGLE)||retryAfterSeconds.filter(v->v<1||v>3600).isPresent())throw PlatformContractSupport.invalid();if(resultKind==PlatformEvidenceResultKind.FAILED_RETRYABLE){if(retryAfterSeconds.isEmpty()||externalIdFingerprint.isPresent()||observedState.isPresent())throw PlatformContractSupport.invalid();}else if(retryAfterSeconds.isPresent())throw PlatformContractSupport.invalid();if(resultKind!=PlatformEvidenceResultKind.SUCCEEDED&&resultKind!=PlatformEvidenceResultKind.FOUND&&(externalIdFingerprint.isPresent()||observedState.isPresent()))throw PlatformContractSupport.invalid();if(attemptKind==PlatformAttemptKind.SUBMIT&&(resultKind==PlatformEvidenceResultKind.FOUND||resultKind==PlatformEvidenceResultKind.NOT_FOUND||resultKind==PlatformEvidenceResultKind.STILL_UNKNOWN))throw PlatformContractSupport.invalid();if(attemptKind==PlatformAttemptKind.RECONCILE&&(resultKind==PlatformEvidenceResultKind.SUCCEEDED||resultKind==PlatformEvidenceResultKind.FAILED_RETRYABLE))throw PlatformContractSupport.invalid();}}
